'use client';

import Link from 'next/link';
import { FormEvent, useState } from 'react';
import { ApiClientError, createPrinter, saveVendorProfile } from '../../lib/api-client';

const split = (value: string) => value.split(',').map((item) => item.trim()).filter(Boolean);

export function VendorStudio() {
  const [status, setStatus] = useState(''); const [slug, setSlug] = useState('');
  const [profile, setProfile] = useState({ businessName: '', bio: '', city: '', state: '', serviceAreas: '' });
  const [printer, setPrinter] = useState({ name: '', model: '', technologies: '', materials: '', minOrderQuantity: '1' });
  async function submitProfile(event: FormEvent) { event.preventDefault(); setStatus('Saving your public page…'); try { await saveVendorProfile({ slug, ...profile, serviceAreas: split(profile.serviceAreas) }); setStatus(`Your page is live at /vendors/${slug}`); } catch (error) { setStatus(error instanceof ApiClientError ? error.message : 'Could not save your page.'); } }
  async function submitPrinter(event: FormEvent) { event.preventDefault(); setStatus('Adding printer…'); try { await createPrinter({ ...printer, technologies: split(printer.technologies), materials: split(printer.materials), minOrderQuantity: Number(printer.minOrderQuantity) }); setStatus('Printer added. Customers will see its MOQ on your page.'); setPrinter({ name: '', model: '', technologies: '', materials: '', minOrderQuantity: '1' }); } catch (error) { setStatus(error instanceof ApiClientError ? error.message : 'Could not add this printer.'); } }
  return <main className="vendor-studio"><Link href="/dashboard/owner" className="back-link">← Owner workspace</Link><div className="studio-intro"><p>YOUR PUBLIC WORKSHOP</p><h1>Make your machines easy to find.</h1><span>Publish a simple vendor page, list every printer, and let customers contact you directly.</span></div><div className="studio-grid"><form className="studio-card" onSubmit={submitProfile}><p className="eyebrow">01 · Your page</p><h2>Tell customers who you are</h2><label>Public page handle<input required value={slug} onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '-'))} placeholder="acme-prints" /></label><label>Business or workshop name<input required value={profile.businessName} onChange={(e) => setProfile({ ...profile, businessName: e.target.value })} placeholder="Acme 3D Prints" /></label><label>Short introduction<textarea value={profile.bio} onChange={(e) => setProfile({ ...profile, bio: e.target.value })} placeholder="What do you make well?" /></label><div className="two"><label>City<input value={profile.city} onChange={(e) => setProfile({ ...profile, city: e.target.value })} placeholder="Bengaluru" /></label><label>State<input value={profile.state} onChange={(e) => setProfile({ ...profile, state: e.target.value })} placeholder="Karnataka" /></label></div><label>Service areas <small>comma separated</small><input value={profile.serviceAreas} onChange={(e) => setProfile({ ...profile, serviceAreas: e.target.value })} placeholder="Bengaluru, Karnataka, Pan India" /></label><button className="button" type="submit">Publish my page →</button></form><form className="studio-card" onSubmit={submitPrinter}><p className="eyebrow">02 · Your machines</p><h2>List a printer</h2><label>Printer name<input required value={printer.name} onChange={(e) => setPrinter({ ...printer, name: e.target.value })} placeholder="Bambu Lab P1S" /></label><label>Model or build notes<input value={printer.model} onChange={(e) => setPrinter({ ...printer, model: e.target.value })} placeholder="Enclosed · 256mm build volume" /></label><label>Technologies <small>comma separated</small><input value={printer.technologies} onChange={(e) => setPrinter({ ...printer, technologies: e.target.value })} placeholder="FDM, multi-colour" /></label><label>Materials <small>comma separated</small><input value={printer.materials} onChange={(e) => setPrinter({ ...printer, materials: e.target.value })} placeholder="PLA, PETG, TPU" /></label><label>Minimum order quantity<input required min="1" type="number" value={printer.minOrderQuantity} onChange={(e) => setPrinter({ ...printer, minOrderQuantity: e.target.value })} /></label><p className="hint">MOQ is the smallest number of parts you accept for this printer. Customers will see it before contacting you.</p><button className="button dark" type="submit">Add printer →</button></form></div>{status && <p className="studio-status" role="status">{status}</p>}<style jsx>{`.vendor-studio{min-height:100vh;background:#f6f7f2;color:#20221e;padding:32px max(20px,calc((100vw - 1080px)/2));font-family:Arial,sans-serif}.back-link{color:#6d7168;text-decoration:none;font-size:13px}.studio-intro{padding:72px 0 38px;max-width:650px}.studio-intro p,.eyebrow{font-size:11px;letter-spacing:.14em;color:#ef6847;font-weight:700}.studio-intro h1{font-size:clamp(38px,6vw,68px);line-height:.98;letter-spacing:-.06em;margin:16px 0}.studio-intro span{color:#70746b;line-height:1.6}.studio-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.studio-card{background:#fffefa;border:1px solid #dedfd8;border-radius:12px;padding:28px;display:grid;gap:15px}.studio-card h2{font-size:24px;letter-spacing:-.04em;margin:0 0 8px}.studio-card label{display:grid;gap:7px;font-size:12px;font-weight:700}.studio-card small{color:#9a9d95;font-weight:400}.studio-card input,.studio-card textarea{border:1px solid #d9dbd2;border-radius:6px;padding:12px;font:inherit;font-size:13px;background:#fff}.studio-card textarea{min-height:90px;resize:vertical}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.button{border:0;border-radius:6px;background:#ef6847;color:white;padding:14px;font-weight:700;cursor:pointer;margin-top:4px}.button.dark{background:#20221e}.hint{font-size:11px;line-height:1.5;color:#7d8177;margin:0}.studio-status{margin:18px 0;color:#277b60;font-size:13px}@media(max-width:700px){.studio-grid{grid-template-columns:1fr}.studio-intro{padding-top:52px}}`}</style></main>;
}
